#!/usr/bin/env node

/**
 * cli.js - Command-Line Interface for Music Sheet Enhancer
 */

const fs = require('fs');
const path = require('path');
const {
  generateCleanSheetHtml,
  generateWorkbookHtml,
  generateSinglePageHtml,
  renderHtmlToPdf,
  findBrowserExecutable,
  loadLocaleFromFile,
  resolveLocale,
  validateExercises
} = require('../src/index');

const pkg = require('../package.json');

function printHelp() {
  console.log(`
Music Sheet Enhancer v${pkg.version}
Vectorize blurry music sheets into faithful 1:1 clean editions first, plus optional reference keys and kids workbooks.

USAGE:
  music-sheet-enhancer [options]
  node bin/cli.js [options]

OPTIONS:
  -f, --format <type>       Format to generate:
                            clean | clean-reference | workbook | workbook-answers |
                            single | single-answers | kids | all
                            (default: "clean")
  -l, --lang <code>         Language / BCP 47 culture code:
                            en | zh-CN | zh-HK | zh-TW | en-US | zh-Hant ...
                            (default: "en")
  -d, --data <file>         Path to custom exercises JSON dataset
                            (default: "data/note-exercises.json")
  -o, --out <dir>           Output directory (default: "dist")
  -t, --title <text>        Explicit sheet title (overrides dataset title in clean format)
  --pdf                     Compile to PDF via headless browser (Edge/Chrome)
  --no-html                 Do not keep generated HTML files after PDF compilation
  --standalone              Embed VexFlow inline for 100% offline self-contained HTML
  --locale-file <file>      Path to custom locale dictionary JSON file
  -h, --help                Show this help message
  -v, --version             Display version information

EXAMPLES:
  # Default: faithful 1:1 clean restoration (no extra descriptions)
  music-sheet-enhancer --data data/note-step-on-staff.json --out dist/note-step-on-the-staff --pdf

  # Clean restoration with note letters reference key
  music-sheet-enhancer --format clean-reference --data data/note-step-on-staff.json --out dist/note-step-on-the-staff --pdf

  # Generate 4-page Kids Workbook & Answer Key when explicitly requested
  music-sheet-enhancer --format kids --lang zh-HK --pdf

  # Generate all formats (clean + reference + kids workbook + single sheet)
  music-sheet-enhancer --format all --lang zh-TW --pdf
`);
}

function toSafeFileBase(text) {
  return String(text || '')
    .trim()
    .replace(/[<>:"/\\|?*]+/g, '')
    .replace(/\s+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function parseArgs(args) {
  const options = {
    format: 'clean',
    lang: 'en',
    data: path.resolve(__dirname, '..', 'data', 'note-exercises.json'),
    out: path.resolve(process.cwd(), 'dist'),
    title: null,
    pdf: false,
    html: true,
    standalone: true,
    localeFile: null
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];

    if (arg === '-h' || arg === '--help') {
      printHelp();
      process.exit(0);
    }
    if (arg === '-v' || arg === '--version') {
      console.log(`v${pkg.version}`);
      process.exit(0);
    }
    if ((arg === '-f' || arg === '--format') && args[i + 1]) {
      options.format = args[++i];
    } else if ((arg === '-l' || arg === '--lang') && args[i + 1]) {
      options.lang = args[++i];
    } else if ((arg === '-d' || arg === '--data') && args[i + 1]) {
      options.data = path.resolve(args[++i]);
    } else if ((arg === '-o' || arg === '--out') && args[i + 1]) {
      options.out = path.resolve(args[++i]);
    } else if ((arg === '-t' || arg === '--title') && args[i + 1]) {
      options.title = args[++i];
    } else if (arg === '--pdf') {
      options.pdf = true;
    } else if (arg === '--no-html') {
      options.html = false;
    } else if (arg === '--standalone') {
      options.standalone = true;
    } else if (arg === '--locale-file' && args[i + 1]) {
      options.localeFile = path.resolve(args[++i]);
    }
  }

  return options;
}

async function run() {
  const options = parseArgs(process.argv.slice(2));

  if (options.localeFile) {
    if (!fs.existsSync(options.localeFile)) {
      console.error(`Error: Custom locale file not found: ${options.localeFile}`);
      process.exit(1);
    }
    try {
      const registeredCode = loadLocaleFromFile(options.localeFile);
      options.lang = registeredCode;
      console.log(`✓ Loaded custom locale from ${options.localeFile} as [${registeredCode}]`);
    } catch (err) {
      console.error(`Error loading locale file: ${err.message}`);
      process.exit(1);
    }
  }

  const resolvedLocale = resolveLocale(options.lang);
  console.log(`🎵 Music Sheet Enhancer`);
  console.log(`   Format:   ${options.format}`);
  console.log(`   Locale:   ${resolvedLocale} (requested: "${options.lang}")`);
  console.log(`   Data:     ${options.data}`);
  console.log(`   Output:   ${options.out}`);
  console.log(`   PDF Mode: ${options.pdf ? 'Enabled' : 'Disabled'}`);

  if (!fs.existsSync(options.data)) {
    console.error(`Error: Exercise data file not found at: ${options.data}`);
    process.exit(1);
  }

  let dataset;
  try {
    dataset = JSON.parse(fs.readFileSync(options.data, 'utf8'));
  } catch (err) {
    console.error(`Error parsing JSON from ${options.data}: ${err.message}`);
    process.exit(1);
  }

  const validation = validateExercises(dataset);
  const metaTitle = validation.meta && validation.meta.title ? validation.meta.title : null;
  const resolvedTitle = options.title || metaTitle;
  const cleanBase = toSafeFileBase(resolvedTitle) || `Clean_Music_Sheet_${resolvedLocale}`;

  if (!fs.existsSync(options.out)) {
    fs.mkdirSync(options.out, { recursive: true });
  }

  const tasks = [];
  const fmt = options.format.toLowerCase();

  if (fmt === 'clean' || fmt === 'all') {
    tasks.push({
      name: cleanBase,
      type: 'clean',
      isAnswerKey: false
    });
  }
  if (fmt === 'clean-reference' || fmt === 'clean-answers' || fmt === 'all') {
    tasks.push({
      name: `${cleanBase}_Reference`,
      type: 'clean',
      isAnswerKey: true
    });
  }
  if (fmt === 'all' || fmt === 'kids' || fmt === 'workbook') {
    tasks.push({
      name: `Note_Reading_Workbook_Kids_${resolvedLocale}`,
      type: 'workbook',
      isAnswerKey: false
    });
  }
  if (fmt === 'all' || fmt === 'kids' || fmt === 'workbook-answers') {
    tasks.push({
      name: `Note_Reading_Workbook_Answer_Key_${resolvedLocale}`,
      type: 'workbook',
      isAnswerKey: true
    });
  }
  if (fmt === 'all' || fmt === 'single') {
    tasks.push({
      name: `Note_Reading_Single_Page_${resolvedLocale}`,
      type: 'single',
      isAnswerKey: false
    });
  }
  if (fmt === 'all' || fmt === 'single-answers') {
    tasks.push({
      name: `Note_Reading_Single_Page_Answers_${resolvedLocale}`,
      type: 'single',
      isAnswerKey: true
    });
  }

  if (tasks.length === 0) {
    console.error(`Error: Unknown format "${options.format}". Allowed values: clean, clean-reference, workbook, workbook-answers, single, single-answers, kids, all.`);
    process.exit(1);
  }

  let browserAvailable = null;
  if (options.pdf) {
    browserAvailable = findBrowserExecutable();
    if (!browserAvailable) {
      console.warn(`⚠️ Warning: Headless browser not detected. PDF compilation will be skipped.`);
    }
  }

  for (const task of tasks) {
    const htmlFileName = `${task.name}.html`;
    const htmlFilePath = path.join(options.out, htmlFileName);

    let html;
    if (task.type === 'clean') {
      html = generateCleanSheetHtml({
        exercises: dataset,
        title: options.title,
        locale: resolvedLocale,
        isAnswerKey: task.isAnswerKey,
        standalone: options.standalone
      });
    } else if (task.type === 'workbook') {
      html = generateWorkbookHtml({
        exercises: dataset,
        locale: resolvedLocale,
        isAnswerKey: task.isAnswerKey,
        standalone: options.standalone
      });
    } else {
      html = generateSinglePageHtml({
        exercises: dataset,
        locale: resolvedLocale,
        isAnswerKey: task.isAnswerKey,
        standalone: options.standalone
      });
    }

    fs.writeFileSync(htmlFilePath, html, 'utf8');
    console.log(`  ✓ Generated HTML: ${htmlFileName}`);

    if (options.pdf && browserAvailable) {
      const pdfFileName = `${task.name}.pdf`;
      const pdfFilePath = path.join(options.out, pdfFileName);
      console.log(`    Compiling PDF: ${pdfFileName}...`);
      const res = renderHtmlToPdf(htmlFilePath, pdfFilePath);
      if (res.success) {
        console.log(`    ✓ PDF created: ${pdfFileName}`);
        if (!options.html) {
          fs.unlinkSync(htmlFilePath);
        }
      } else {
        console.error(`    ✗ PDF compilation failed: ${res.error}`);
      }
    }
  }

  console.log(`\n🎉 All tasks completed successfully! Output stored in: ${options.out}`);
}

if (require.main === module) {
  run();
}

module.exports = { parseArgs, toSafeFileBase };

#!/usr/bin/env node

/**
 * verify.js - CLI Verification Loop Runner for Music Sheet Enhancer
 * Runs domain checks (schema, note counts, pitch ranges, stepwise continuity),
 * full-width PDF scan extraction/cropping, 1:1 visual comparison generation, and temp cleanup.
 */

const fs = require('fs');
const path = require('path');
const {
  verifyNoteDataset,
  extractRawScanFromPdf,
  cropAndGridScanImage,
  buildComparisonSheet,
  cleanupTempDir
} = require('../src/verifier');

function printHelp() {
  console.log(`
Music Sheet Enhancer - Verification Runner

USAGE:
  node bin/verify.js [options]

OPTIONS:
  -d, --data <file>      Exercises JSON file to validate
  -s, --scan <pdf|img>   Source scanned PDF or image to deskew & crop from x=0
  -o, --out <dir>        Temporary verification directory (default: ".verify-tmp")
  --angle <deg>          Deskew rotation in degrees (default: 0)
  --stepwise             Enforce strict +/-1 diatonic stepwise adjacent intervals
  --compare              Generate 1:1 stacked compare_all.html/.pdf in --out
  --clean                Delete the temporary verification directory (--out)
  -h, --help             Show this help message
`);
}

function parseVerifyArgs(args) {
  const opts = {
    data: null,
    scan: null,
    out: path.resolve(process.cwd(), '.verify-tmp'),
    angle: 0,
    stepwise: undefined,
    compare: false,
    clean: false
  };

  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (a === '-h' || a === '--help') {
      printHelp();
      process.exit(0);
    } else if ((a === '-d' || a === '--data') && args[i + 1]) {
      opts.data = path.resolve(args[++i]);
    } else if ((a === '-s' || a === '--scan') && args[i + 1]) {
      opts.scan = path.resolve(args[++i]);
    } else if ((a === '-o' || a === '--out') && args[i + 1]) {
      opts.out = path.resolve(args[++i]);
    } else if (a === '--angle' && args[i + 1]) {
      opts.angle = Number(args[++i]) || 0;
    } else if (a === '--stepwise') {
      opts.stepwise = true;
    } else if (a === '--compare') {
      opts.compare = true;
    } else if (a === '--clean') {
      opts.clean = true;
    }
  }

  return opts;
}

async function run() {
  const opts = parseVerifyArgs(process.argv.slice(2));

  if (opts.clean && !opts.data && !opts.scan) {
    cleanupTempDir(opts.out);
    console.log(`Cleaned temporary directory: ${opts.out}`);
    return;
  }

  let scanDir = null;
  if (opts.scan) {
    if (!fs.existsSync(opts.scan)) {
      console.error(`Error: Scan file not found: ${opts.scan}`);
      process.exit(1);
    }
    fs.mkdirSync(opts.out, { recursive: true });
    let imagePath = opts.scan;
    if (opts.scan.toLowerCase().endsWith('.pdf')) {
      const extracted = path.join(opts.out, 'raw_scan.jpg');
      await extractRawScanFromPdf(opts.scan, extracted);
      imagePath = extracted;
    }
    const cropRes = await cropAndGridScanImage(imagePath, opts.out, { angle: opts.angle });
    scanDir = opts.out;
    console.log(`Extracted ${cropRes.strips.length} stave strip(s) to ${opts.out}`);
  }

  if (opts.data) {
    if (!fs.existsSync(opts.data)) {
      console.error(`Error: Dataset not found: ${opts.data}`);
      process.exit(1);
    }
    const dataset = JSON.parse(fs.readFileSync(opts.data, 'utf8'));
    const report = verifyNoteDataset(dataset, { stepwise: opts.stepwise });

    console.log(`Total notes: ${report.totalNotes}`);
    for (const s of report.staveSummaries) {
      console.log(`  Stave ${s.id} (${s.clef}, ${s.count} notes, range ${s.minPitch}..${s.maxPitch}): stepwiseErrors=${s.stepwiseErrors}`);
    }

    if (!report.schemaValid) {
      console.error('Schema errors:', report.schemaErrors.join('\n'));
    }
    if (report.countMismatches.length > 0) {
      console.error('Count mismatches:', report.countMismatches);
    }
    if (report.stepwiseViolations.length > 0) {
      console.error('Stepwise (+/-1) violations:', report.stepwiseViolations);
    }

    if (opts.compare) {
      const cmp = buildComparisonSheet({
        dataset,
        scanDir: scanDir || opts.out,
        outputDir: opts.out,
        stepwise: opts.stepwise,
        compilePdf: true
      });
      console.log(`Generated comparison sheet: ${cmp.pdfPath}`);
    }

    if (opts.clean) {
      cleanupTempDir(opts.out);
      console.log(`Cleaned temporary directory: ${opts.out}`);
    }

    if (!report.valid) {
      process.exit(1);
    }
    return;
  }

  if (!opts.scan && !opts.clean) {
    printHelp();
  }
}

if (require.main === module) {
  run().catch(err => {
    console.error(`Verification failed: ${err.message}`);
    process.exit(1);
  });
}

module.exports = { parseVerifyArgs };

/**
 * index.js - Music Sheet Enhancer Public API
 */

const { generateCleanSheetHtml, generateWorkbookHtml, generateSinglePageHtml } = require('./generator');
const { createTranslator, resolveLocale, registerLocale, loadLocaleFromFile, getAvailableLocales } = require('./i18n');
const { validateExercises, escapeHtml } = require('./validator');
const { renderHtmlToPdf, findBrowserExecutable } = require('./pdf-renderer');
const { verifyNoteDataset, diatonicValue, buildComparisonSheet, cleanupTempDir } = require('./verifier');

module.exports = {
  // Generation
  generateCleanSheetHtml,
  generateWorkbookHtml,
  generateSinglePageHtml,

  // Verification & Self-Check
  verifyNoteDataset,
  diatonicValue,
  buildComparisonSheet,
  cleanupTempDir,

  // PDF Rendering
  renderHtmlToPdf,
  findBrowserExecutable,

  // i18n
  createTranslator,
  resolveLocale,
  registerLocale,
  loadLocaleFromFile,
  getAvailableLocales,

  // Validation & Security
  validateExercises,
  escapeHtml
};
